enum LookupError {
    Unavailable(String),
    InvalidId,
}

struct User {
    const id: i64;
    const name: String;
}

fn findUser(id: i64) -> Result<Option<User>, LookupError> {
    if (id < 0) {
        return Err(LookupError::InvalidId);
    }
    if (id == 42) {
        return Ok(Some(User { id: 42, name: "Alice" }));
    }
    if (id == 500) {
        return Err(LookupError::Unavailable("Database unavailable"));
    }
    return Ok(None);
}

fn userName(id: i64) -> Result<String, LookupError> {
    const user = findUser(id)?;
    return Ok(match (user) {
        Some(found) => found.name,
        None => "Anonymous",
    });
}

fn report(id: i64) {
    println(match (userName(id)) {
        Ok(name) => name,
        Err(error) => match (error) {
            LookupError::Unavailable(message) => message,
            LookupError::InvalidId => "Invalid user ID",
        },
    });
}

fn main() {
    report(42);
    report(7);
    report(-1);
    report(500);
}

fn consume(value: Option<i64>) -> i64 {
    return match (value) { Some(n) => n, None => 0 };
  } fn main() {
    let value: Option<i64> = None;
    println(consume(value)); value = Some(9);
    println(consume(value)); println(consume(None));
    const inferred = Some(4); println(consume(inferred));
  }

struct Box { let value: Option<Result<Option<i64>,String>>; }
  fn main() {
    const box = Box { value: Some(Ok(Some(8))) };
    const result: Result<Option<i64>,String> = match (box.value) { Some(r) => r, None => Err("missing") };
    println(match (result) { Ok(value) => match (value) { Some(n) => n, None => 0 }, Err(_) => -1 });
  }

enum Event { Empty, Pair(i64,String) }
    fn main() { const n = 10; const e = Event::Pair(3,"hello");
      println(match (e) { Event::Empty => "empty", Event::Pair(n,message) => message });
      println(n);
      println(match (e) { Event::Empty => 0, Event::Pair(n,_) => n });
    }

fn subject() -> Option<i64> { println("subject"); return Some(1); }
    fn arm() -> i64 { println("wrong arm"); return 0; }
    fn main() { println(10 + match (subject()) { Some(n) => n, None => arm() }); }

fn step(ok: bool) -> Result<i64,String> {
      if (ok) { return Ok(3); } return Err("failed");
    }
    fn next(ok: bool) -> Result<String,String> {
      if (true) { const n = 100 + step(ok)?; println(n); }
      println("continued"); return Ok("done");
    }
    fn main() {
      println(match (next(false)) { Ok(s) => s, Err(e) => e });
      println(match (next(true)) { Ok(s) => s, Err(e) => e });
    }

fn step(ok: bool) -> Option<i64> { if (ok) { return Some(1); } return None; }
    fn next(ok: bool) -> Option<String> { const n = step(ok)?; return Some("found"); }
    fn main() {
      println(match (next(false)) { Some(s) => s, None => "missing" });
      println(match (next(true)) { Some(s) => s, None => "missing" });
    }

struct S { let n: i64; } enum E { Value(S), Shared(&S) }
    fn main() {
      let original = S { n: 1 }; const e = E::Value(original); original.n = 2;
      println(match (e) { E::Value(s) => s.n, E::Shared(s) => s.n });
      const shared = &S { n: 3 }; const refEnum = E::Shared(shared); shared.n = 4;
      println(match (refEnum) { E::Value(s) => s.n, E::Shared(s) => s.n });
    }

struct S { let n: i64; }
    fn mutate(s: &S) -> i64 { s.n += 1; return s.n; }
    fn main() { const s = &S { n: 0 }; const value = Some(s);
      println(match (value) { Some(target) => mutate(target), None => -1 }); println(s.n);
    }
